def choose_move(observation):
    # Defensive defaults
    # Try to read a few common fields defensively
    top_down = observation.get("top_down", False)
    actions = observation.get("legal_actions", [])
    pos = observation.get("position", observation.get("pos", None))
    grid = observation.get("grid", observation.get("terrain", None))
    goals = observation.get("goal", None)
    enemies = observation.get("enemies", None)
    resources = observation.get("resources", None)
    territory = observation.get("territory", None)
    # Baseline: stay in place
    dx = 0
    dy = 0

    # Prefer simple reactive rules that work across modes
    # 1) If there is a resource nearby, move toward it
    if resources:
        # resources expected as a list of (x,y) or dicts
        def to_xy(r):
            if isinstance(r, dict):
                x = r.get("x", r.get("px", None))
                y = r.get("y", r.get("py", None))
                return (x, y) if x is not None and y is not None else None
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                return (r[0], r[1])
            return None

        best = None
        if isinstance(resources, dict):
            # maybe a multiset with positions
            for k, v in resources.items():
                p = to_xy(v)
                if p and pos is not None:
                    dx2 = p[0] - pos[0]
                    dy2 = p[1] - pos[1]
                    dist = abs(dx2) + abs(dy2)
                    if best is None or dist < best[0]:
                        best = (dist, dx2, dy2)
        elif isinstance(resources, (list, tuple)):
            for r in resources:
                p = to_xy(r)
                if p and pos is not None:
                    dx2 = p[0] - pos[0]
                    dy2 = p[1] - pos[1]
                    dist = abs(dx2) + abs(dy2)
                    if best is None or dist < best[0]:
                        best = (dist, dx2, dy2)
        if best:
            dx = 0
            dy = 0
            if best[1] != 0:
                dx = 1 if best[1] > 0 else -1
            elif best[2] != 0:
                dy = 1 if best[2] > 0 else -1
            return [dx, dy]

    # 2) If an enemy is nearby, move away from the closest threat
    if enemies:
        def get_closest_threat():
            closest = None
            if isinstance(enemies, dict):
                items = enemies.values()
            else:
                items = enemies
            for e in items:
                if not isinstance(e, (list, tuple)) or pos is None:
                    continue
                ex, ey = (e[0], e[1]) if len(e) >= 2 else (None, None)
                if ex is None:
                    continue
                dist = abs(ex - pos[0]) + abs(ey - pos[1])
                if closest is None or dist < closest[0]:
                    closest = (dist, ex, ey)
            return closest
        threat = get_closest_threat()
        if threat:
            dx_diff = (threat[1] - pos[0])
            dy_diff = (threat[2] - pos[1])
            # move opposite
            if abs(dx_diff) > abs(dy_diff):
                dx = -1 if dx_diff > 0 else 1
            else:
                dy = -1 if dy_diff > 0 else 1
            return [dx, dy]

    # 3) If territory control present, try to move towards center of own territory if possible
    if territory:
        if isinstance(territory, dict):
            center = territory.get("center")
        else:
            center = None
        if center and pos is not None:
            tx, ty = center[0], center[1]
            dx = 0
            dy = 0
            if tx > pos[0]:
                dx = 1
            elif tx < pos[0]:
                dx = -1
            if dy == 0 and ty != pos[1]:
                dy = 1 if ty > pos[1] else -1
            return [dx, dy]

    # 4) Default exploration: try to move in a deterministic small pattern
    # Use a simple priority: right, down, left, up
    if top_down:
        # If top-down view, favor horizontal move first
        for cand in [(1,0), (0,1), (-1,0), (0,-1)]:
            dx, dy = cand
            if (dx, dy) in [(1,0), (0,1), (-1,0), (0,-1)]:
                return [dx, dy]
    else:
        # General default
        for cand in [(0,1), (1,0), (0,-1), (-1,0)]:
            dx, dy = cand
            return [dx, dy]

    return [0, 0]

